  void initState() {
    super.initState();
    _themeModeNotifier = ValueNotifier(_settingsRepository.readThemeMode());
    _themeModeSub = _settingsRepository.themeModeStream.listen(_themeModeNotifier.value);
    _initAnimation();
  }

